exec('\nfrom __future__ import annotations\n\nimport time\nimport datetime as dt\nimport warnings\nfrom pathlib import Path\nfrom urllib.parse import quote_plus\nimport xml.etree.ElementTree as ET\n\nimport numpy as np\nimport pandas as pd\nimport plotly.graph_objects as go\nimport requests\nimport streamlit as st\nimport yfinance as yf\n\nfrom sklearn.linear_model import Ridge, ElasticNet, HuberRegressor\nfrom sklearn.ensemble import RandomForestRegressor, ExtraTreesRegressor, GradientBoostingRegressor, VotingRegressor\nfrom sklearn.metrics import mean_squared_error\n\nwarnings.filterwarnings("ignore")\nROOT = Path(__file__).resolve().parents[1]\n\nAPP_TITLE = "MatQuantLab"\nAPP_SUBTITLE = "Material-driven industrial risk research"\nAPP_DESCRIPTION = "A focused workbench for tracing material, energy, macro and event shocks into selected assets."\n\n# -----------------------------------------------------------------------------\n# Built-in domain map\n# -----------------------------------------------------------------------------\nMATERIALS = {\n    "Copper": {"long": "Copper — grids, motors, electronics, construction, EV demand", "family": "industrial metals", "tickers": ["HG=F", "CPER", "COPX"], "keywords": ["copper", "grid", "electrification", "copper mine"], "weight": .11},\n    "Aluminum": {"long": "Aluminum — aerospace, transport, packaging, power-intensive smelting", "family": "industrial metals", "tickers": ["ALI=F", "AA"], "keywords": ["aluminum", "aluminium", "smelter", "bauxite", "alumina"], "weight": .09},\n    "Nickel": {"long": "Nickel — stainless steel, superalloys, batteries, turbine alloys", "family": "superalloys and batteries", "tickers": ["JJN", "VALE", "NILSY"], "keywords": ["nickel", "superalloy", "stainless steel"], "weight": .08},\n    "Steel": {"long": "Steel chain — iron ore, steel, coking coal, industrial capex", "family": "steel chain", "tickers": ["SLX", "MT", "NUE", "X", "TIO=F", "HCC"], "keywords": ["steel", "iron ore", "coking coal", "blast furnace"], "weight": .075},\n    "Lithium": {"long": "Lithium — battery supply chain and EV demand", "family": "battery materials", "tickers": ["LIT", "ALB", "SQM", "PLL"], "keywords": ["lithium", "spodumene", "battery"], "weight": .075},\n    "Cobalt": {"long": "Cobalt — cathode material and geopolitical supply concentration", "family": "battery materials", "tickers": ["COB.AX", "GLEN.L", "VALE"], "keywords": ["cobalt", "cathode", "DRC"], "weight": .045},\n    "Graphite": {"long": "Graphite — battery anode and China processing risk", "family": "battery materials", "tickers": ["NMG", "SYAAF", "TGR.AX"], "keywords": ["graphite", "anode", "battery anode"], "weight": .045},\n    "Rare earths": {"long": "Rare earths — magnets, EV motors, defense electronics, export controls", "family": "critical minerals", "tickers": ["REMX", "MP", "LYC.AX"], "keywords": ["rare earth", "neodymium", "dysprosium", "magnet", "NdFeB"], "weight": .09},\n    "Titanium": {"long": "Titanium — aerospace, medical implants, AM powder feedstock", "family": "AM / aerospace powder materials", "tickers": ["ATI", "TROX", "CRS"], "keywords": ["titanium", "titanium sponge", "titanium powder", "Ti-6Al-4V"], "weight": .07},\n    "Tungsten": {"long": "Tungsten — hard metals, tooling, defense, high-density alloys", "family": "defense and tooling materials", "tickers": ["TUNG.L", "ALMTF"], "keywords": ["tungsten", "carbide", "hard metal"], "weight": .04},\n    "Uranium": {"long": "Uranium — nuclear fuel and energy security", "family": "energy security", "tickers": ["URA", "URNM", "CCJ"], "keywords": ["uranium", "nuclear fuel", "enrichment"], "weight": .07},\n    "Oil": {"long": "Crude oil — fuel, logistics, inflation and Middle East risk", "family": "energy inputs", "tickers": ["CL=F", "BZ=F", "USO", "XLE"], "keywords": ["oil", "crude", "OPEC", "fuel", "refinery"], "weight": .10},\n    "Natural gas": {"long": "Natural gas — power, heat treatment, HIP, atomization and process energy", "family": "energy inputs", "tickers": ["NG=F", "UNG"], "keywords": ["natural gas", "LNG", "gas", "power price"], "weight": .08},\n    "Gold": {"long": "Gold — safe-haven, real rates and geopolitical stress", "family": "precious metals", "tickers": ["GC=F", "GLD"], "keywords": ["gold", "bullion", "central bank gold", "safe haven"], "weight": .07},\n    "Silver": {"long": "Silver — precious/industrial hybrid, solar and electronics", "family": "precious metals", "tickers": ["SI=F", "SLV"], "keywords": ["silver", "solar", "precious metal"], "weight": .045},\n    "Platinum": {"long": "Platinum — catalysts, hydrogen, industrial demand", "family": "precious industrial metals", "tickers": ["PL=F", "PPLT"], "keywords": ["platinum", "catalyst", "hydrogen"], "weight": .04},\n    "Palladium": {"long": "Palladium — auto catalysts and supply risk", "family": "precious industrial metals", "tickers": ["PA=F", "PALL"], "keywords": ["palladium", "catalyst"], "weight": .04},\n}\n\nFUTURES = {\n    "WTI crude oil": "CL=F",\n    "Brent oil": "BZ=F",\n    "Natural gas": "NG=F",\n    "Copper": "HG=F",\n    "Gold": "GC=F",\n    "Silver": "SI=F",\n    "Platinum": "PL=F",\n    "Palladium": "PA=F",\n    "Iron ore proxy": "TIO=F",\n    "US dollar index": "DX-Y.NYB",\n    "VIX": "^VIX",\n    "US 10Y yield": "^TNX",\n    "Gold ETF": "GLD",\n    "Silver ETF": "SLV",\n    "Oil ETF": "USO",\n    "Natural gas ETF": "UNG",\n    "Uranium ETF": "URA",\n    "Rare earth ETF": "REMX",\n    "Lithium/battery ETF": "LIT",\n    "Steel ETF": "SLX",\n}\n\nCORE_ASSETS = {\n    "SPY": {"name": "SPDR S&P 500 ETF", "group": "market benchmark", "keywords": ["S&P 500", "market", "equity"]},\n    "XME": {"name": "SPDR Metals & Mining ETF", "group": "mining/metals", "keywords": ["mining", "metals", "iron ore", "steel"]},\n    "COPX": {"name": "Global X Copper Miners ETF", "group": "copper miners", "keywords": ["copper", "copper mine", "copper supply"]},\n    "ITA": {"name": "iShares U.S. Aerospace & Defense ETF", "group": "aerospace/defense", "keywords": ["aerospace", "defense", "procurement"]},\n    "XAR": {"name": "SPDR Aerospace & Defense ETF", "group": "aerospace supply chain", "keywords": ["aerospace", "defense", "aircraft"]},\n    "PRNT": {"name": "3D Printing ETF", "group": "additive manufacturing", "keywords": ["additive manufacturing", "3D printing", "metal powder", "LPBF"]},\n    "SOXX": {"name": "iShares Semiconductor ETF", "group": "semiconductors", "keywords": ["semiconductor", "chip", "Taiwan"]},\n    "GLD": {"name": "SPDR Gold Shares", "group": "gold", "keywords": ["gold", "safe haven"]},\n    "SLV": {"name": "iShares Silver Trust", "group": "silver", "keywords": ["silver", "solar", "electronics"]},\n    "USO": {"name": "United States Oil Fund", "group": "oil", "keywords": ["oil", "fuel"]},\n    "UNG": {"name": "United States Natural Gas Fund", "group": "natural gas", "keywords": ["natural gas", "LNG"]},\n    "URA": {"name": "Global X Uranium ETF", "group": "uranium", "keywords": ["uranium", "nuclear fuel"]},\n    "LIT": {"name": "Global X Lithium & Battery Tech ETF", "group": "battery materials", "keywords": ["lithium", "battery"]},\n    "REMX": {"name": "VanEck Rare Earth/Strategic Metals ETF", "group": "rare earths", "keywords": ["rare earth", "magnet", "export controls"]},\n    "SLX": {"name": "VanEck Steel ETF", "group": "steel", "keywords": ["steel", "iron ore", "coal"]},\n}\n\nDEFAULT_COMPANIES = pd.DataFrame([\n    ["ATI", "ATI Inc.", "United States", "specialty alloys", "titanium / nickel / aerospace", "titanium powder, aerospace materials"],\n    ["GE", "GE Aerospace", "United States", "aerospace", "nickel / titanium / turbines", "jet engines, superalloys"],\n    ["BA", "Boeing", "United States", "aerospace", "aluminum / titanium / composites", "aircraft production"],\n    ["LMT", "Lockheed Martin", "United States", "defense", "rare earths / titanium / defense electronics", "defense procurement"],\n    ["RTX", "RTX", "United States", "aerospace/defense", "superalloys / electronics", "engines, missiles, defense"],\n    ["NUE", "Nucor", "United States", "steel", "steel chain", "steel production"],\n    ["AA", "Alcoa", "United States", "aluminum", "aluminum / energy", "smelting power cost"],\n    ["FCX", "Freeport-McMoRan", "United States", "copper mining", "copper", "copper producer"],\n    ["AIR.PA", "Airbus", "France", "aerospace", "aluminum / titanium / aerospace", "aircraft production"],\n    ["SAF.PA", "Safran", "France", "aerospace", "nickel / titanium / engines", "jet engines"],\n    ["HO.PA", "Thales", "France", "defense electronics", "rare earths / semiconductors", "defense electronics"],\n    ["RR.L", "Rolls-Royce", "United Kingdom", "aerospace", "nickel / titanium / engines", "jet engines"],\n    ["BA.L", "BAE Systems", "United Kingdom", "defense", "defense / rare earths", "defense systems"],\n    ["RIO.L", "Rio Tinto", "United Kingdom", "mining", "iron ore / aluminum / copper", "diversified mining"],\n    ["GLEN.L", "Glencore", "United Kingdom", "mining/trading", "copper / cobalt / coal", "commodity supply"],\n    ["RHM.DE", "Rheinmetall", "Germany", "defense", "steel / defense", "munitions, vehicles"],\n    ["SIE.DE", "Siemens", "Germany", "industrial automation", "copper / electrification", "automation and grids"],\n    ["BAS.DE", "BASF", "Germany", "chemicals", "gas / energy / chemicals", "feedstock cost"],\n    ["VOW3.DE", "Volkswagen", "Germany", "autos", "steel / aluminum / batteries", "vehicle manufacturing"],\n    ["ASML.AS", "ASML", "Netherlands", "semiconductor equipment", "semiconductors / rare earths", "lithography"],\n    ["NXPI", "NXP Semiconductors", "Netherlands", "semiconductors", "auto chips / electronics", "industrial electronics"],\n    ["1211.HK", "BYD", "China", "EV/batteries", "lithium / batteries / rare earths", "EV and battery chain"],\n    ["2899.HK", "Zijin Mining", "China", "mining", "copper / gold / lithium", "metals mining"],\n    ["600019.SS", "Baoshan Iron & Steel", "China", "steel", "steel chain", "steel production"],\n    ["7203.T", "Toyota", "Japan", "autos", "steel / aluminum / batteries", "vehicle production"],\n    ["7011.T", "Mitsubishi Heavy Industries", "Japan", "heavy industry/aerospace", "aerospace / defense / energy", "industrial systems"],\n    ["5713.T", "Sumitomo Metal Mining", "Japan", "mining/materials", "nickel / copper / batteries", "battery materials"],\n    ["005930.KS", "Samsung Electronics", "South Korea", "semiconductors", "chips / electronics", "semiconductors"],\n    ["373220.KS", "LG Energy Solution", "South Korea", "batteries", "lithium / nickel / cobalt", "battery manufacturing"],\n    ["005490.KS", "POSCO Holdings", "South Korea", "steel/materials", "steel / batteries", "steel and battery materials"],\n    ["2330.TW", "TSMC", "Taiwan", "semiconductors", "chips / Taiwan risk", "foundry"],\n    ["BHP.AX", "BHP", "Australia", "mining", "iron ore / copper / coal", "global mining"],\n    ["LYC.AX", "Lynas Rare Earths", "Australia", "rare earths", "rare earths / NdPr", "rare earth supply"],\n    ["PLS.AX", "Pilbara Minerals", "Australia", "lithium", "lithium", "spodumene"],\n], columns=["ticker", "company", "country", "industry_group", "material_link", "why_relevant"])\n\n# -----------------------------------------------------------------------------\n# Load optional repo data\n# -----------------------------------------------------------------------------\ndef load_csv(path: str, fallback: pd.DataFrame) -> pd.DataFrame:\n    p = ROOT / path\n    try:\n        if p.exists():\n            df = pd.read_csv(p)\n            if not df.empty:\n                return df\n    except Exception:\n        pass\n    return fallback\n\ncompanies = load_csv("data/manufacturing_company_universe.csv", DEFAULT_COMPANIES)\n\n# -----------------------------------------------------------------------------\n# Helpers\n# -----------------------------------------------------------------------------\ndef interval_minutes(interval: str) -> int:\n    if interval.endswith("m"):\n        return int(interval[:-1])\n    if interval == "1d":\n        return 1440\n    return 1440\n\ndef compatible_period(interval: str, requested: str) -> str:\n    if interval == "1m":\n        return requested if requested in ["1d", "5d"] else "5d"\n    if interval in ["5m", "15m", "30m", "60m"]:\n        return requested if requested in ["1d", "5d", "1mo", "3mo", "6mo"] else "60d"\n    return requested\n\ndef adaptive_window(n: int, requested: int) -> int:\n    if n < 40:\n        return max(2, n // 6)\n    if n < 120:\n        return max(4, min(requested, n // 5))\n    return max(5, min(requested, 100))\n\ndef safe_pct_change(s: pd.Series, lag: int) -> pd.Series:\n    return s.pct_change(max(1, lag)).replace([np.inf, -np.inf], np.nan)\n\ndef zscore(s: pd.Series, window: int) -> pd.Series:\n    window = max(3, int(window))\n    mean = s.rolling(window, min_periods=max(3, window // 3)).mean()\n    std = s.rolling(window, min_periods=max(3, window // 3)).std()\n    return ((s - mean) / std).replace([np.inf, -np.inf], np.nan)\n\ndef series_change(df: pd.DataFrame, col: str, bars: int = 20) -> float:\n    if col not in df or df[col].dropna().empty:\n        return 0.0\n    s = df[col].dropna()\n    bars = min(max(1, bars), len(s) - 1) if len(s) > 1 else 1\n    if len(s) <= bars:\n        return 0.0\n    return float((s.iloc[-1] / s.iloc[-bars - 1]) - 1)\n\ndef plain_direction(x: float, pos="rising", neg="falling", flat="flat") -> str:\n    if x > 0.03:\n        return pos\n    if x < -0.03:\n        return neg\n    return flat\n\ndef horizon_delta(interval: str, horizon: int) -> dt.timedelta:\n    return dt.timedelta(minutes=interval_minutes(interval) * horizon)\n\ndef validity_text(last_ts, interval: str, horizon: int, top_drivers: list[str], features: pd.DataFrame) -> str:\n    try:\n        until = pd.Timestamp(last_ts) + horizon_delta(interval, horizon)\n        until_s = str(until)[:16]\n    except Exception:\n        until_s = "the next horizon window"\n\n    invalidate = []\n    for d in top_drivers[:3]:\n        if d in features.columns:\n            latest = features[d].dropna()\n            if len(latest):\n                val = float(latest.iloc[-1])\n                invalidate.append(f"{d} moves back toward 0 from {val:.2f} or flips sign")\n    if not invalidate:\n        invalidate.append("the top drivers reverse direction")\n    return f"Useful until about {until_s}, or earlier if " + "; ".join(invalidate) + "."\n\ndef make_query(base_terms: list[str], focus_assets: list[str]) -> str:\n    terms = list(base_terms)\n    # Add asset-specific words so news changes with selected assets.\n    for a in focus_assets:\n        if a in CORE_ASSETS:\n            terms += CORE_ASSETS[a].get("keywords", [])\n        company_row = companies[companies["ticker"].astype(str) == a]\n        if not company_row.empty:\n            r = company_row.iloc[0]\n            terms += [str(r["company"]), str(r["material_link"]), str(r["industry_group"])]\n        for mat, spec in MATERIALS.items():\n            if a in spec["tickers"]:\n                terms += spec["keywords"] + [mat]\n    clean = []\n    for t in terms:\n        for part in str(t).replace("/", " ").split(","):\n            p = part.strip()\n            if p and p.lower() not in [x.lower() for x in clean]:\n                clean.append(p)\n    return "(" + " OR ".join(clean[:60]) + ")"\n\n@st.cache_data(ttl=45, show_spinner=False)\ndef download_prices(tickers, period, interval):\n    tickers = sorted(set([t for t in tickers if isinstance(t, str) and t.strip()]))\n    if not tickers:\n        return pd.DataFrame()\n    raw = yf.download(tickers, period=period, interval=interval, auto_adjust=True, progress=False, threads=True, group_by="column")\n    if raw.empty:\n        return pd.DataFrame()\n    if isinstance(raw.columns, pd.MultiIndex):\n        close = raw["Close"].copy() if "Close" in raw.columns.get_level_values(0) else raw.xs("Close", axis=1, level=1, drop_level=True).copy()\n    else:\n        close = raw[["Close"]].copy()\n        if len(tickers) == 1:\n            close.columns = tickers\n    return close.dropna(axis=1, how="all").ffill().dropna(how="all")\n\n@st.cache_data(ttl=360, show_spinner=False)\ndef fetch_gdelt(query, n=50):\n    try:\n        r = requests.get(\n            "https://api.gdeltproject.org/api/v2/doc/doc",\n            params={"query": query, "mode": "ArtList", "format": "json", "maxrecords": n, "sort": "HybridRel"},\n            timeout=10,\n        )\n        if r.status_code != 200:\n            return pd.DataFrame()\n        rows = []\n        for a in r.json().get("articles", []):\n            rows.append({"title": a.get("title", ""), "source": a.get("domain", ""), "date": a.get("seendate", ""), "url": a.get("url", "")})\n        return pd.DataFrame(rows)\n    except Exception:\n        return pd.DataFrame()\n\n@st.cache_data(ttl=900, show_spinner=False)\ndef fetch_google_news(query, n=50):\n    try:\n        url = "https://news.google.com/rss/search?q=" + quote_plus(query) + "&hl=en-US&gl=US&ceid=US:en"\n        r = requests.get(url, timeout=10, headers={"User-Agent": "MatQuantLab/1.0"})\n        if r.status_code != 200:\n            return pd.DataFrame()\n        root = ET.fromstring(r.content)\n        rows = []\n        for item in root.findall(".//item")[:n]:\n            rows.append({"title": (item.findtext("title") or "").strip(), "source": "Google News", "date": (item.findtext("pubDate") or "").strip(), "url": (item.findtext("link") or "").strip()})\n        return pd.DataFrame(rows)\n    except Exception:\n        return pd.DataFrame()\n\n# -----------------------------------------------------------------------------\n# Feature engineering and explanations\n# -----------------------------------------------------------------------------\ndef build_features(prices: pd.DataFrame, shock_window: int):\n    n = len(prices)\n    w = adaptive_window(n, shock_window)\n    lag = max(1, min(w, max(1, n // 4)))\n    feat = pd.DataFrame(index=prices.index)\n    meta = []\n    material_map = {}\n\n    for name, spec in MATERIALS.items():\n        chosen = next((t for t in spec["tickers"] if t in prices.columns), None)\n        if chosen:\n            col = f"material · {name}"\n            feat[col] = zscore(safe_pct_change(prices[chosen], lag), w)\n            meta.append({"feature": col, "source_ticker": chosen, "family": spec["family"], "meaning": spec["long"]})\n            material_map[name] = chosen\n\n    # Always build selected price features too; this makes charts/signals reflect user choice.\n    for t in prices.columns:\n        col = f"asset move · {t}"\n        feat[col] = zscore(safe_pct_change(prices[t], lag), w)\n        meta.append({"feature": col, "source_ticker": t, "family": "selected asset / proxy", "meaning": f"Recent normalized move in {t}"})\n\n    # Family aggregates\n    meta_df = pd.DataFrame(meta)\n    if not meta_df.empty:\n        for fam in sorted(meta_df["family"].dropna().unique()):\n            cols = meta_df.loc[meta_df["family"] == fam, "feature"].tolist()\n            cols = [c for c in cols if c in feat.columns]\n            if cols:\n                feat[f"family · {fam}"] = feat[cols].mean(axis=1)\n\n    material_cols = [c for c in feat.columns if c.startswith("material ·")]\n    if material_cols:\n        feat["material stress composite"] = feat[material_cols].mean(axis=1)\n    else:\n        feat["material stress composite"] = feat.mean(axis=1)\n\n    # Special AM/PM basket\n    def avg_cols(keys):\n        cols = [c for c in keys if c in feat.columns]\n        return feat[cols].mean(axis=1) if cols else pd.Series(index=feat.index, dtype=float)\n\n    feat["AM/PM · powder feedstock pressure"] = avg_cols(["material · Titanium", "material · Nickel", "material · Aluminum", "material · Rare earths"])\n    feat["AM/PM · process energy pressure"] = avg_cols(["material · Natural gas", "material · Oil", "family · energy inputs"])\n    feat["AM/PM · alloy and PM input pressure"] = avg_cols(["material · Steel", "material · Graphite", "material · Nickel", "material · Titanium"])\n    feat["AM/PM · aerospace-defense demand channel"] = avg_cols(["family · AM / aerospace powder materials", "family · defense and tooling materials", "family · critical minerals"])\n    am_cols = [c for c in feat.columns if c.startswith("AM/PM ·")]\n    if am_cols:\n        feat["AM/PM stress basket"] = feat[am_cols].mean(axis=1)\n\n    feat = feat.replace([np.inf, -np.inf], np.nan).dropna(how="all")\n    feat = feat.ffill().fillna(0)\n    return feat, meta_df, material_map, w\n\ndef strongest_drivers(features: pd.DataFrame, selected_assets: list[str], n=20):\n    latest = features.iloc[-1]\n    # prioritize asset-specific and material columns related to chosen assets\n    focus_words = set()\n    for a in selected_assets:\n        focus_words.add(a.lower())\n        if a in CORE_ASSETS:\n            focus_words.update([x.lower() for x in CORE_ASSETS[a].get("keywords", [])])\n        cr = companies[companies["ticker"].astype(str) == a]\n        if not cr.empty:\n            text = " ".join([str(cr.iloc[0].get("material_link", "")), str(cr.iloc[0].get("industry_group", "")), str(cr.iloc[0].get("company", ""))])\n            focus_words.update([w.lower() for w in text.replace("/", " ").replace(",", " ").split() if len(w) > 2])\n\n    rows = []\n    for c, v in latest.items():\n        score = float(v)\n        label = c\n        related = any(w in label.lower() for w in focus_words) if focus_words else False\n        rows.append({"driver": label, "score": score, "abs_score": abs(score), "related_to_selection": related})\n    df = pd.DataFrame(rows)\n    if df.empty:\n        return df\n    df["rank_boost"] = df["abs_score"] + df["related_to_selection"].astype(float) * .35\n    return df.sort_values("rank_boost", ascending=False).head(n)\n\ndef explain_driver(row) -> str:\n    direction = "positive/upward stress" if row["score"] > 0 else "negative/easing pressure"\n    magnitude = "large" if abs(row["score"]) >= 1.5 else "moderate" if abs(row["score"]) >= .75 else "small"\n    return f"{row[\'driver\']} is a {magnitude} {direction} input right now (score {row[\'score\']:.2f})."\n\ndef chart_lines(df, title, ytitle="value", normalize=False):\n    if df.empty:\n        st.info("No data for this chart with the current selection.")\n        return\n    x = df.copy().ffill().dropna(how="all")\n    if normalize and not x.empty:\n        x = x / x.iloc[0]\n    fig = go.Figure()\n    for col in x.columns:\n        fig.add_trace(go.Scatter(x=x.index, y=x[col], mode="lines", name=str(col), hovertemplate=f"{col}<br>%{{x}}<br>%{{y:.4f}}<extra></extra>"))\n    fig.update_layout(title=title, height=430, xaxis_title="time", yaxis_title=ytitle, hovermode="x unified", legend_title="series", margin=dict(l=20, r=20, t=55, b=30))\n    st.plotly_chart(fig, use_container_width=True)\n\ndef chart_bar(df, x, y, title):\n    if df.empty:\n        st.info("No data for this chart with the current selection.")\n        return\n    d = df.copy().sort_values(x)\n    fig = go.Figure(go.Bar(x=d[x], y=d[y], orientation="h", text=[f"{v:.2f}" if isinstance(v, (int,float,np.floating)) else "" for v in d[x]], textposition="auto"))\n    fig.update_layout(title=title, height=max(360, len(d) * 24), xaxis_title=x, yaxis_title="", margin=dict(l=20, r=20, t=55, b=30))\n    st.plotly_chart(fig, use_container_width=True)\n\n# -----------------------------------------------------------------------------\n# ML\n# -----------------------------------------------------------------------------\ndef candidate_models():\n    return {\n        "Ridge": Ridge(alpha=8),\n        "ElasticNet": ElasticNet(alpha=.01, l1_ratio=.2, random_state=42),\n        "Huber": HuberRegressor(epsilon=1.35, alpha=.0001),\n        "RandomForest": RandomForestRegressor(n_estimators=120, max_depth=4, random_state=42, n_jobs=-1),\n        "ExtraTrees": ExtraTreesRegressor(n_estimators=160, max_depth=5, random_state=42, n_jobs=-1),\n        "GradientBoosting": GradientBoostingRegressor(random_state=42, max_depth=2),\n        "Blended": VotingRegressor([\n            ("ridge", Ridge(alpha=8)),\n            ("rf", RandomForestRegressor(n_estimators=80, max_depth=4, random_state=42, n_jobs=-1)),\n            ("gb", GradientBoostingRegressor(random_state=42, max_depth=2)),\n        ])\n    }\n\ndef fit_eval(model, Xtr, ytr, Xte, yte):\n    model.fit(Xtr, ytr)\n    pred = model.predict(Xte)\n    corr = pd.Series(pred).corr(pd.Series(yte.values))\n    corr = 0 if pd.isna(corr) else float(corr)\n    rmse = float(mean_squared_error(yte, pred) ** .5)\n    vol = max(float(ytr.std()), 1e-8)\n    score = corr - .10 * min(rmse / vol, 5)\n    return model, pred, corr, rmse, score\n\ndef model_importance(model, cols):\n    if hasattr(model, "feature_importances_"):\n        return pd.Series(model.feature_importances_, index=cols).sort_values(ascending=False)\n    if hasattr(model, "coef_"):\n        co = np.array(model.coef_).reshape(-1)\n        return pd.Series(np.abs(co), index=cols[:len(co)]).sort_values(ascending=False)\n    if hasattr(model, "estimators_"):\n        parts = []\n        for e in model.estimators_:\n            if hasattr(e, "feature_importances_"):\n                parts.append(pd.Series(e.feature_importances_, index=cols))\n            elif hasattr(e, "coef_"):\n                co = np.array(e.coef_).reshape(-1)\n                parts.append(pd.Series(np.abs(co), index=cols[:len(co)]))\n        if parts:\n            return pd.concat(parts, axis=1).mean(axis=1).sort_values(ascending=False)\n    return pd.Series(0, index=cols)\n\ndef trust_level(conf, corr, test_rows):\n    if test_rows < 8:\n        return "low", "not enough test observations"\n    if corr > .12 and conf > .50:\n        return "higher", "prediction had useful recent alignment"\n    if corr > .03 and conf > .33:\n        return "medium", "prediction had mild recent alignment"\n    if corr > 0:\n        return "low-medium", "alignment is positive but weak"\n    return "low", "recent validation did not support the direction"\n\ndef stance(direction, strength, trust):\n    if trust in ["higher", "medium"] and strength in ["strong", "moderate"]:\n        return "positive pressure" if direction == "positive" else "negative pressure"\n    if direction == "positive" and strength in ["moderate", "strong"]:\n        return "mild positive pressure"\n    if direction == "negative" and strength in ["moderate", "strong"]:\n        return "risk watch"\n    return "no reliable signal"\n\ndef train_asset(asset, prices, features, horizon, interval, model_choice):\n    if asset not in prices.columns:\n        return None, None\n    px = prices[asset].dropna()\n    if len(px) < 15 or len(features) < 15:\n        return None, None\n\n    effective_h = max(1, min(int(horizon), max(1, min(len(px), len(features)) // 8)))\n    def make_df(h):\n        y = prices[asset].pct_change(h).shift(-h).rename("future_return")\n        X = features.copy()\n        # Keep only non-constant features\n        X = X.loc[:, X.std() > 1e-9]\n        return pd.concat([X, y], axis=1, join="inner").dropna(subset=["future_return"])\n    df = make_df(effective_h)\n    if len(df) < 25:\n        effective_h = max(1, min(5, horizon))\n        df = make_df(effective_h)\n    if len(df) < 16:\n        effective_h = 1\n        df = make_df(1)\n    if len(df) < 12:\n        return None, None\n\n    feature_cols = [c for c in df.columns if c != "future_return"]\n    df[feature_cols] = df[feature_cols].fillna(0)\n    split = max(8, int(len(df) * .70))\n    if split >= len(df) - 3:\n        split = max(6, len(df) - 4)\n    tr, te = df.iloc[:split], df.iloc[split:]\n    if len(te) < 3:\n        return None, None\n\n    Xtr, ytr = tr[feature_cols], tr["future_return"].astype(float)\n    Xte, yte = te[feature_cols], te["future_return"].astype(float)\n\n    models = candidate_models()\n    if model_choice == "Adaptive":\n        best = None\n        for name, model in models.items():\n            try:\n                m, pred, corr, rmse, score = fit_eval(model, Xtr, ytr, Xte, yte)\n                if best is None or score > best["score"]:\n                    best = {"name": name, "model": m, "pred": pred, "corr": corr, "rmse": rmse, "score": score}\n            except Exception:\n                pass\n        if best is None:\n            return None, None\n        model, pred, corr, rmse, model_name = best["model"], best["pred"], best["corr"], best["rmse"], best["name"]\n    else:\n        try:\n            model, pred, corr, rmse, _ = fit_eval(models[model_choice], Xtr, ytr, Xte, yte)\n            model_name = model_choice\n        except Exception:\n            return None, None\n\n    latest_pred = float(model.predict(features.iloc[[-1]][feature_cols].fillna(0))[0])\n    vol = max(float(ytr.std()), 1e-8)\n    conf = min(abs(latest_pred) / (vol * 1.25), 1)\n    direction = "positive" if latest_pred > 0 else "negative"\n    strength = "strong" if conf > .66 else "moderate" if conf > .33 else "weak"\n    trust, trust_reason = trust_level(conf, corr, len(te))\n    stn = stance(direction, strength, trust)\n    imp = model_importance(model, feature_cols)\n    drivers = [x for x in imp.index[:3]]\n\n    validity = validity_text(px.index[-1], interval, effective_h, drivers, features)\n    msg = (\n        f"{asset}: {stn}. The model estimates {direction} pressure over {effective_h} {interval} bars. "\n        f"Trust is {trust} because {trust_reason}. Main drivers: {\', \'.join(drivers) if drivers else \'not stable\'}. {validity}"\n    )\n    curve = te.copy()\n    curve["prediction"] = pred\n    curve["model_position"] = np.where(curve["prediction"] > 0, 1, -1)\n    curve["diagnostic_curve"] = (1 + curve["model_position"] * curve["future_return"].fillna(0)).cumprod()\n\n    row = {\n        "asset": asset,\n        "model": model_name,\n        "stance": stn,\n        "direction": direction,\n        "strength": strength,\n        "trust": trust,\n        "prediction": latest_pred,\n        "confidence": conf,\n        "test_corr": corr,\n        "rmse": rmse,\n        "effective_horizon": effective_h,\n        "validity": validity,\n        "driver_1": drivers[0] if len(drivers) > 0 else "",\n        "driver_2": drivers[1] if len(drivers) > 1 else "",\n        "driver_3": drivers[2] if len(drivers) > 2 else "",\n        "data_start": str(pd.Timestamp(df.index[0]))[:16],\n        "data_end": str(pd.Timestamp(df.index[-1]))[:16],\n        "message": msg,\n    }\n    return row, curve\n\n# -----------------------------------------------------------------------------\n# Domain interpretation\n# -----------------------------------------------------------------------------\ndef annotate_asset(asset):\n    if asset in CORE_ASSETS:\n        x = CORE_ASSETS[asset]\n        return x["name"], x["group"], ", ".join(x["keywords"])\n    cr = companies[companies["ticker"].astype(str) == asset]\n    if not cr.empty:\n        r = cr.iloc[0]\n        return str(r["company"]), str(r["industry_group"]), str(r["material_link"])\n    for name, tick in FUTURES.items():\n        if tick == asset:\n            return name, "commodity / future / proxy", name\n    return asset, "selected instrument", asset\n\ndef asset_relevant_features(asset, features):\n    name, group, text = annotate_asset(asset)\n    words = set(str(text).lower().replace("/", " ").replace(",", " ").split())\n    words.update([asset.lower(), group.lower()])\n    if "additive" in text.lower() or asset == "PRNT":\n        words.update(["AM/PM", "titanium", "nickel", "aluminum", "powder", "energy"])\n    cols = []\n    for c in features.columns:\n        low = c.lower()\n        if any(w and w in low for w in words):\n            cols.append(c)\n    if "material stress composite" in features.columns:\n        cols.append("material stress composite")\n    if "AM/PM stress basket" in features.columns and ("additive" in text.lower() or "aerospace" in text.lower() or asset == "PRNT"):\n        cols.append("AM/PM stress basket")\n    return list(dict.fromkeys([c for c in cols if c in features.columns]))[:12]\n\ndef build_transmission(selected_assets, features, gscore):\n    rows = []\n    latest = features.iloc[-1]\n    for a in selected_assets:\n        name, group, material_link = annotate_asset(a)\n        cols = asset_relevant_features(a, features)\n        if not cols:\n            cols = ["material stress composite"] if "material stress composite" in features.columns else list(features.columns[:3])\n        val = float(latest[cols].mean()) if cols else 0.0\n        path = " → ".join([c.replace("material · ", "").replace("family · ", "").replace("AM/PM · ", "") for c in cols[:4]])\n        rows.append({\n            "asset": a,\n            "name": name,\n            "group": group,\n            "material link": material_link,\n            "transmission score": val,\n            "current reading": "stress closer to this asset" if val > .5 else "easing near this asset" if val < -.5 else "mixed/neutral",\n            "main path": path,\n        })\n    return pd.DataFrame(rows).sort_values("transmission score", ascending=False)\n\ndef contradictions(selected_assets, features, signals, gscore):\n    rows = []\n    latest = features.iloc[-1]\n    def add(title, meaning, related="system", severity="medium"):\n        rows.append({"check": title, "related asset": related, "meaning": meaning, "severity": severity})\n    # generic\n    if gscore > 2 and abs(float(latest.get("material stress composite", 0))) < .5:\n        add("Event risk high but material stress not extreme", "Headlines are active, but prices have not fully confirmed the shock.", "selected universe", "medium")\n    gold = latest.get("material · Gold", np.nan)\n    vix_cols = [c for c in features.columns if "VIX" in c]\n    vix = latest[vix_cols].mean() if vix_cols else np.nan\n    if pd.notna(gold) and pd.notna(vix) and vix > .7 and gold < 0:\n        add("Volatility rising without gold confirmation", "Risk appetite is weaker, but safe-haven metal behavior does not confirm it.", "gold / macro", "medium")\n    # asset-specific\n    if signals is not None and not signals.empty:\n        for _, r in signals.iterrows():\n            a = r["asset"]\n            rel_cols = asset_relevant_features(a, features)\n            rel_score = float(latest[rel_cols].mean()) if rel_cols else 0\n            if rel_score < -.6 and r["direction"] == "positive":\n                add("Model positive while mapped material path is easing", "Equity/future signal is stronger than material fundamentals. Check momentum and validation.", a, "high")\n            if rel_score > .8 and r["direction"] == "negative":\n                add("Model negative while mapped material path is stressed upward", "Input stress may be acting as a cost/risk channel rather than a demand channel.", a, "high")\n    if not rows:\n        add("No major contradiction detected", "Current event, material and signal layers do not show a strong conflict under the built-in checks.", "selected universe", "low")\n    return pd.DataFrame(rows)\n\ndef narrative_for_selection(selected_assets, prices, features, signals, gscore):\n    latest = features.iloc[-1]\n    material_score = float(latest.get("material stress composite", 0))\n    if material_score > .8:\n        stress = "material stress is elevated"\n    elif material_score < -.8:\n        stress = "material stress is easing"\n    else:\n        stress = "material stress is mixed"\n    asset_text = ", ".join(selected_assets[:5]) + ("..." if len(selected_assets) > 5 else "")\n    best = ""\n    if signals is not None and not signals.empty:\n        r = signals.iloc[0]\n        best = f"The most actionable selected signal is {r[\'asset\']} with {r[\'stance\']} and {r[\'trust\']} trust."\n    else:\n        best = "No selected asset produced a reliable model signal."\n    return f"For the selected universe ({asset_text}), {stress}. Event risk is {gscore:.2f}. {best}"\n\n# -----------------------------------------------------------------------------\n# App\n# -----------------------------------------------------------------------------\nst.set_page_config(page_title="MatQuantLab", layout="wide")\nst.title(APP_TITLE)\nst.subheader(APP_SUBTITLE)\nst.caption(APP_DESCRIPTION)\n\nwith st.sidebar:\n    st.header("Research setup")\n    st.caption("Selections drive the charts, news query, transmission map and model signals.")\n\n    universe = st.radio("Universe", ["Core assets", "Manufacturing companies", "Commodities/futures", "Everything"], index=3)\n\n    country_filter = []\n    if not companies.empty:\n        country_filter = st.multiselect("Country filter", sorted(companies["country"].dropna().unique().tolist()), default=[])\n\n    company_tickers = sorted(companies["ticker"].astype(str).tolist()) if not companies.empty else []\n    futures_tickers = sorted(set(FUTURES.values()))\n    core_tickers = sorted(CORE_ASSETS.keys())\n\n    if universe == "Core assets":\n        choices = core_tickers\n    elif universe == "Manufacturing companies":\n        choices = company_tickers\n    elif universe == "Commodities/futures":\n        choices = futures_tickers\n    else:\n        choices = sorted(set(core_tickers + company_tickers + futures_tickers))\n\n    if country_filter and universe in ["Manufacturing companies", "Everything"]:\n        c_ticks = companies.loc[companies["country"].isin(country_filter), "ticker"].astype(str).tolist()\n        choices = sorted(set(c_ticks + (core_tickers + futures_tickers if universe == "Everything" else [])))\n\n    default_assets = [x for x in ["SPY", "COPX", "XME", "PRNT", "GLD", "SLV", "USO", "URA", "REMX"] if x in choices]\n    assets = st.multiselect("Assets to analyze", choices, default=default_assets[:8])\n\n    interval = st.selectbox("Data interval", ["1m", "5m", "15m", "30m", "60m", "1d"], index=5)\n    period = st.selectbox("History", ["1d", "5d", "1mo", "3mo", "6mo", "1y", "2y", "5y", "10y"], index=7)\n    model_choice = st.selectbox("Model selection", ["Adaptive", "Ridge", "ElasticNet", "Huber", "RandomForest", "ExtraTrees", "GradientBoosting", "Blended"], index=0)\n    horizon = st.slider("Forecast horizon, in bars", 1, 120, 10)\n    shock_window = st.slider("Shock window, in bars", 2, 150, 20)\n\n    st.markdown("**Event search**")\n    base_terms = st.multiselect(\n        "Base event terms",\n        sorted(set(["critical minerals", "rare earth", "Iran", "Strait of Hormuz", "Red Sea", "oil", "gas", "LNG", "gold", "silver", "China", "Taiwan", "sanctions", "export controls", "titanium powder", "powder metallurgy", "LPBF", "EBM", "HIP", "aerospace backlog", "defense procurement"])),\n        default=["critical minerals", "rare earth", "oil", "gas", "gold", "China", "sanctions", "export controls", "powder metallurgy"]\n    )\n    extra_terms = st.text_input("Extra event terms, comma separated", value="")\n    if extra_terms:\n        base_terms += [x.strip() for x in extra_terms.split(",") if x.strip()]\n\n    fast_mode = st.toggle("Fast mode", value=True, help="Downloads fewer non-selected proxies for faster refresh. Turn off for richer stress maps.")\n    auto = st.toggle("Auto-refresh", value=False)\n    refresh_seconds = st.selectbox("Refresh every", [30, 60, 120, 300], index=1)\n    if st.button("Refresh now"):\n        st.cache_data.clear()\n        st.rerun()\n\nif auto:\n    time.sleep(refresh_seconds)\n    st.cache_data.clear()\n    st.rerun()\n\nif not assets:\n    st.warning("Choose at least one asset to analyze.")\n    st.stop()\n\nactual_period = compatible_period(interval, period)\nquery = make_query(base_terms, assets)\n\n# Download only what matters first. This is faster and makes the app selection-specific.\nmaterial_proxy_tickers = []\nfor a in assets:\n    # Add related material proxies by asset keywords/company text\n    text = " ".join(annotate_asset(a)).lower()\n    for mat, spec in MATERIALS.items():\n        if any(k.lower() in text for k in [mat] + spec["keywords"]):\n            material_proxy_tickers += spec["tickers"][:2]\nif not material_proxy_tickers or not fast_mode:\n    for spec in MATERIALS.values():\n        material_proxy_tickers += spec["tickers"][:1]\n\nessential = ["SPY", "^VIX", "DX-Y.NYB", "GC=F", "CL=F", "NG=F", "HG=F", "SI=F"]\ntickers = sorted(set(assets + material_proxy_tickers + essential + ([] if fast_mode else list(FUTURES.values()))))\nprices = download_prices(tickers, actual_period, interval)\n\nif prices.empty:\n    st.error("No market data loaded. Try daily interval, fewer assets, or a shorter universe.")\n    st.stop()\n\nfeatures, meta, material_map, effective_window = build_features(prices, shock_window)\nif features.empty:\n    st.error("No usable features were built. Try daily data or select common assets such as SPY, GLD, USO, XME.")\n    st.stop()\n\n# Train signals only for selected assets\nsig_rows, curves = [], {}\nfor a in assets:\n    row, curve = train_asset(a, prices, features, horizon, interval, model_choice)\n    if row:\n        name, group, link = annotate_asset(a)\n        row["name"] = name\n        row["group"] = group\n        row["material link"] = link\n        sig_rows.append(row)\n        curves[a] = curve\n\nsignals = pd.DataFrame(sig_rows)\nif not signals.empty:\n    signals = signals.sort_values(["trust", "confidence"], ascending=[True, False])\n    # Better ordering for trust strings\n    order = {"higher": 0, "medium": 1, "low-medium": 2, "low": 3}\n    signals["_trust_order"] = signals["trust"].map(order).fillna(9)\n    signals = signals.sort_values(["_trust_order", "confidence"], ascending=[True, False]).drop(columns=["_trust_order"])\n\n# News tied to selected assets\nnews_gdelt = fetch_gdelt(query, 60)\nnews_google = fetch_google_news(query, 50)\nnews = pd.concat([x for x in [news_gdelt, news_google] if not x.empty], ignore_index=True) if (not news_gdelt.empty or not news_google.empty) else pd.DataFrame()\n\ndef news_score(news_df):\n    if news_df.empty:\n        return 0.0, pd.DataFrame()\n    themes = {\n        "energy / fuel": ["oil", "gas", "lng", "fuel", "opec", "refinery", "hormuz"],\n        "critical minerals": ["critical minerals", "rare earth", "lithium", "cobalt", "nickel", "graphite", "titanium"],\n        "AM / powder metallurgy": ["powder metallurgy", "additive manufacturing", "3d printing", "metal powder", "lpbf", "ebm", "hip"],\n        "aerospace / defense": ["aerospace", "defense", "missile", "aircraft", "procurement"],\n        "China / export controls": ["china", "taiwan", "export control", "sanction", "tariff"],\n        "gold / silver": ["gold", "silver", "bullion", "safe haven"],\n    }\n    text = " ".join(news_df["title"].fillna("").str.lower().tolist())\n    rows = []\n    score = 0\n    for theme, words in themes.items():\n        c = sum(text.count(w) for w in words)\n        rows.append({"theme": theme, "mentions": c})\n        score += c\n    return min(score / 10, 4.0), pd.DataFrame(rows).sort_values("mentions", ascending=False)\n\ngscore, theme_df = news_score(news)\ntransmission = build_transmission(assets, features, gscore)\ncontra = contradictions(assets, features, signals, gscore)\nbrief = narrative_for_selection(assets, prices, features, signals, gscore)\n\n# Upper band, selection-specific\nm1, m2, m3, m4, m5, m6 = st.columns(6)\nm1.metric("Selected assets", len(assets))\nm2.metric("Material stress", f"{features[\'material stress composite\'].iloc[-1]:.2f}")\nm3.metric("Event risk", f"{gscore:.2f}")\nm4.metric("Signals", len(signals))\nm5.metric("Actual history", actual_period)\nm6.metric("Latest bar", str(prices.index[-1])[:16])\n\nif actual_period != period:\n    st.warning(f"Requested {period} with {interval} data. The app used {actual_period}, which is more realistic for that interval.")\nst.info(brief)\n\ntabs = st.tabs(["Brief", "Stress Monitor", "Exposure Map", "Signals", "News & Events", "Data Quality"])\n\n# -----------------------------------------------------------------------------\n# Brief\n# -----------------------------------------------------------------------------\nwith tabs[0]:\n    st.subheader("Selected-universe brief")\n    st.markdown(brief)\n\n    col1, col2 = st.columns([1.2, 1])\n    with col1:\n        st.markdown("### What matters for your current selection")\n        drivers = strongest_drivers(features, assets, 12)\n        if not drivers.empty:\n            for _, r in drivers.head(6).iterrows():\n                st.write("• " + explain_driver(r))\n        else:\n            st.write("No stable drivers found.")\n    with col2:\n        st.markdown("### Main contradictions")\n        st.dataframe(contra, use_container_width=True, hide_index=True)\n\n    st.markdown("### How to use this screen")\n    st.markdown("""\n- Start here after changing assets or interval.\n- The brief, drivers, news query and transmission map are rebuilt around the assets you selected.\n- A positive driver is not automatically good. For a producer it can mean revenue pressure/opportunity; for a manufacturer it can mean input-cost stress.\n- A signal is useful only when the trust level and drivers make sense.\n""")\n\n# -----------------------------------------------------------------------------\n# Stress Monitor\n# -----------------------------------------------------------------------------\nwith tabs[1]:\n    st.subheader("Stress monitor")\n    relevant_cols = []\n    for a in assets:\n        relevant_cols += asset_relevant_features(a, features)\n    relevant_cols += ["material stress composite", "AM/PM stress basket"]\n    relevant_cols = [c for c in dict.fromkeys(relevant_cols) if c in features.columns]\n\n    chart_lines(features[relevant_cols[:16]], "Stress series relevant to selected assets", "z-score stress")\n    st.markdown("""\n**Reading the trend:**  \nValues are normalized stress scores. Around 0 is normal. Above +1 means the series is unusually strong or stressed. Below -1 means easing or negative pressure.  \nFor manufacturers, positive input stress can mean cost pressure. For commodity producers, the same positive stress can mean stronger pricing power.\n""")\n\n    drivers = strongest_drivers(features, assets, 20)\n    chart_bar(drivers.sort_values("score"), "score", "driver", "Strongest selected-universe drivers")\n    st.markdown("### Driver interpretation")\n    for _, r in drivers.head(8).iterrows():\n        st.write("• " + explain_driver(r))\n\n    am_cols = [c for c in ["AM/PM · powder feedstock pressure", "AM/PM · process energy pressure", "AM/PM · alloy and PM input pressure", "AM/PM · aerospace-defense demand channel", "AM/PM stress basket"] if c in features.columns]\n    if am_cols:\n        st.markdown("### Additive manufacturing and powder metallurgy")\n        chart_lines(features[am_cols], "AM / powder metallurgy stress components", "z-score stress")\n        st.markdown("""\nThis section follows the metal-powder chain: feedstock metals, process energy, alloy/PM inputs and aerospace-defense demand.  \nIf powder feedstock and process energy rise together, AM/PM economics become more difficult even if demand is healthy.  \nIf aerospace-defense demand rises while input stress is stable, the setup is more constructive for AM-linked assets.\n""")\n\n    st.markdown("### Commodity / future / proxy series")\n    ftab = pd.DataFrame([{"instrument": k, "ticker": v, "loaded": v in prices.columns} for k, v in FUTURES.items()])\n    st.dataframe(ftab, use_container_width=True, hide_index=True)\n    loaded_f = [x for x in ftab.loc[ftab["loaded"], "ticker"].tolist() if x in prices.columns]\n    chosen_f = st.multiselect("Chart commodity/future/proxy series", loaded_f, default=loaded_f[:8])\n    if chosen_f:\n        chart_lines(prices[chosen_f], "Commodity/future/proxy series, normalized", "normalized price", normalize=True)\n        st.markdown("""\nThe normalized chart starts every series at 1.0. It is for comparing direction, not absolute prices.  \nUse it to see whether energy, precious metals, copper, volatility and the dollar are moving together or diverging.\n""")\n\n# -----------------------------------------------------------------------------\n# Exposure Map\n# -----------------------------------------------------------------------------\nwith tabs[2]:\n    st.subheader("Exposure map")\n    st.markdown("The exposure map is rebuilt around the selected assets. It shows where the current material stress can transmit.")\n    st.dataframe(transmission, use_container_width=True, hide_index=True)\n    if not transmission.empty:\n        chart_bar(transmission[["asset", "transmission score"]], "transmission score", "asset", "Current transmission score by selected asset")\n        st.markdown("""\n**How to read it:**  \nA high positive transmission score means the selected asset is close to the current shock path.  \nA negative score means mapped inputs are easing or moving against that asset\'s usual exposure.  \nThe score is not a price forecast; it is a materials-to-market routing measure.\n""")\n\n    st.markdown("### Company/material context")\n    rows = []\n    for a in assets:\n        name, group, link = annotate_asset(a)\n        rows.append({"asset": a, "name": name, "group": group, "material/process link": link})\n    st.dataframe(pd.DataFrame(rows), use_container_width=True, hide_index=True)\n\n# -----------------------------------------------------------------------------\n# Signals\n# -----------------------------------------------------------------------------\nwith tabs[3]:\n    st.subheader("Signals")\n    st.markdown("""\nSignals are trained only for the assets you selected.  \nThe output is a research pressure label, not a trading instruction.\n""")\n    if signals.empty:\n        st.warning("No model signals for this selection. Try daily data, longer history, fewer assets or common tickers.")\n    else:\n        cols = ["asset", "name", "group", "stance", "strength", "trust", "model", "prediction", "confidence", "test_corr", "driver_1", "driver_2", "driver_3", "effective_horizon", "validity", "message"]\n        st.dataframe(signals[cols], use_container_width=True, hide_index=True)\n\n        selected_signal = st.selectbox("Inspect one signal", signals["asset"].tolist())\n        row = signals[signals["asset"] == selected_signal].iloc[0]\n        st.markdown(f"### {selected_signal} — {row[\'name\']}")\n        s1, s2, s3, s4 = st.columns(4)\n        s1.metric("Stance", row["stance"])\n        s2.metric("Trust", row["trust"])\n        s3.metric("Test corr.", f"{row[\'test_corr\']:.3f}")\n        s4.metric("Horizon", f"{row[\'effective_horizon\']} bars")\n        st.write(row["message"])\n\n        if selected_signal in curves:\n            curve = curves[selected_signal]\n            chart_lines(curve[["prediction", "future_return"]], f"{selected_signal}: prediction vs later return", "return")\n            st.markdown("""\nIf the prediction and later return move in the same direction often, the model has recent alignment.  \nIf they frequently disagree, reduce trust even when the latest stance looks strong.\n""")\n            chart_lines(curve[["diagnostic_curve"]], f"{selected_signal}: diagnostic curve", "index")\n            st.caption("Diagnostic only. This is not a production backtest.")\n\n    st.markdown("### Options context")\n    opt_asset = st.selectbox("Options ticker", assets if assets else ["SPY", "GLD", "USO"])\n    try:\n        tk = yf.Ticker(opt_asset)\n        expiries = list(tk.options)\n    except Exception:\n        expiries = []\n    if not expiries:\n        st.info("No options chain found for this ticker. Try SPY, XME, COPX, ITA, GLD, SLV or USO.")\n    else:\n        exp = st.selectbox("Expiration", expiries)\n        try:\n            ch = tk.option_chain(exp)\n            calls, puts = ch.calls.copy(), ch.puts.copy()\n            cvol, pvol = calls["volume"].fillna(0).sum(), puts["volume"].fillna(0).sum()\n            coi, poi = calls["openInterest"].fillna(0).sum(), puts["openInterest"].fillna(0).sum()\n            o1, o2, o3, o4 = st.columns(4)\n            o1.metric("Call volume", int(cvol))\n            o2.metric("Put volume", int(pvol))\n            o3.metric("Put/Call volume", f"{pvol/max(cvol,1):.2f}")\n            o4.metric("Put/Call open interest", f"{poi/max(coi,1):.2f}")\n            st.markdown("Options context helps confirm or challenge the signal. High put/call can be hedging or bearish demand; it is not automatically a sell signal.")\n            st.dataframe(calls[["contractSymbol", "strike", "lastPrice", "bid", "ask", "volume", "openInterest", "impliedVolatility"]].sort_values("openInterest", ascending=False).head(30), use_container_width=True)\n            st.dataframe(puts[["contractSymbol", "strike", "lastPrice", "bid", "ask", "volume", "openInterest", "impliedVolatility"]].sort_values("openInterest", ascending=False).head(30), use_container_width=True)\n        except Exception:\n            st.info("Options data could not be loaded for the selected expiration.")\n\n# -----------------------------------------------------------------------------\n# News & Events\n# -----------------------------------------------------------------------------\nwith tabs[4]:\n    st.subheader("News and events")\n    st.caption("The query is automatically expanded using your selected assets and extra event terms.")\n    st.code(query)\n    n1, n2, n3 = st.columns(3)\n    n1.metric("Event risk", f"{gscore:.2f}")\n    n2.metric("Headlines", len(news))\n    n3.metric("Search terms", len(query.split(" OR ")))\n\n    if not theme_df.empty:\n        st.markdown("### Event themes for this selection")\n        st.dataframe(theme_df, use_container_width=True, hide_index=True)\n        chart_bar(theme_df.rename(columns={"mentions": "score", "theme": "driver"}), "score", "driver", "News theme intensity")\n\n    st.markdown("""\n**How to use this section:**  \nIf the model signal is negative but news is quiet, the move may be price/technical rather than event-driven.  \nIf event risk is high but prices are calm, watch for delayed transmission.  \nIf news themes match the model drivers, the signal is more coherent.\n""")\n\n    if news.empty:\n        st.info("No news returned. Use fewer terms or a broader query.")\n    else:\n        st.dataframe(news[["title", "source", "date", "url"]].head(120), use_container_width=True, hide_index=True)\n\n# -----------------------------------------------------------------------------\n# Data Quality\n# -----------------------------------------------------------------------------\nwith tabs[5]:\n    st.subheader("Data quality")\n    q1, q2, q3, q4 = st.columns(4)\n    q1.metric("Requested history", period)\n    q2.metric("Actual history", actual_period)\n    q3.metric("Price rows", len(prices))\n    q4.metric("Feature rows", len(features))\n    st.write(f"Price coverage: `{prices.index[0]}` → `{prices.index[-1]}`")\n    st.write(f"Effective shock window: `{effective_window}`")\n    if actual_period != period:\n        st.warning("The history was adjusted because the selected interval cannot support the requested period.")\n\n    st.markdown("### Loaded price series")\n    st.dataframe(prices.tail(100), use_container_width=True)\n    st.markdown("### Feature metadata")\n    st.dataframe(meta, use_container_width=True, hide_index=True)\n    st.markdown("### Latest feature values")\n    latest_features = features.iloc[-1].sort_values(key=lambda s: s.abs(), ascending=False).rename("latest score").reset_index().rename(columns={"index": "feature"})\n    st.dataframe(latest_features.head(80), use_container_width=True, hide_index=True)\n\nst.divider()\nst.caption("Research workbench. Free public market/news data may be delayed, incomplete or unavailable. Signals are diagnostics, not investment advice.")\n')
